// ============================================================
//  MONTAR LOTES — lista de ~100 ações (IBrX) dividida em grupos
//  >>> COLE SEU TOKEN DA BRAPI na linha TOKEN abaixo <<<
//  Modo do node: "Run Once for All Items"
// ============================================================

const TOKEN = 'COLE_SEU_TOKEN_AQUI';     // <<< troque aqui
const TICKERS_POR_LOTE = 1;              // plano grátis: 1 ação por requisição
const RANGE = '3mo';                      // plano grátis: máximo 3 meses
const INTERVAL = '1d';                    // candle diário

// Universo de ações líquidas (IBrX) — edite à vontade.
const tickers = [
  'ABEV3','ALOS3','ALPA4','ASAI3','AURE3','AZUL4','AZZA3','B3SA3','BBAS3','BBDC3',
  'BBDC4','BBSE3','BEEF3','BPAC11','BRAP4','BRFS3','BRKM5','CCRO3','CMIG4','CMIN3',
  'COGN3','CPFE3','CPLE6','CRFB3','CSAN3','CSNA3','CVCB3','CXSE3','CYRE3','DXCO3',
  'EGIE3','ELET3','ELET6','EMBR3','ENEV3','ENGI11','EQTL3','EZTC3','FLRY3','GGBR4',
  'GMAT3','GOAU4','HAPV3','HYPE3','IGTI11','ITSA4','ITUB4','JBSS3','KLBN11','LREN3',
  'LWSA3','MGLU3','MRFG3','MRVE3','MULT3','NTCO3','PCAR3','PETR3','PETR4','PETZ3',
  'PRIO3','PSSA3','RADL3','RAIL3','RAIZ4','RDOR3','RECV3','RENT3','SANB11','SBSP3',
  'SLCE3','SMTO3','SUZB3','TAEE11','TIMS3','TOTS3','TRPL4','UGPA3','USIM5','VALE3',
  'VAMO3','VBBR3','VIVA3','VIVT3','WEGE3','YDUQ3','POMO4','CASH3','MOVI3','SMFT3'
];

const lotes = [];
for (let i = 0; i < tickers.length; i += TICKERS_POR_LOTE) {
  const grupo = tickers.slice(i, i + TICKERS_POR_LOTE);
  const url = 'https://brapi.dev/api/quote/' + grupo.join(',') +
              '?range=' + RANGE + '&interval=' + INTERVAL + '&token=' + TOKEN;
  lotes.push({ json: { url: url, lote: grupo.join(',') } });
}
return lotes;

// ============================================================
//  CÉREBRO v13 — SCANNER + AVALIAÇÃO 3:1 (cabe alvo de 3x o stop antes do nível?)
//  Lê o ^BVSP junto e diz se o ativo está A FAVOR ou CONTRA a maré.
//  Mostra: força + direção da tendência, suportes/resistências
//  históricos, distância até eles, e rompimento/teste de nível.
//  Você decide no gráfico. Cole no node "Cerebro do Funil".
//  Modo do node: "Run Once for All Items"
// ============================================================

// ---------- AJUSTES ----------
const EMA_CURTO = 9, EMA_LONGO = 21, EMA_MEDIA = 50;
const PERIODO_ADX = 14, PERIODO_RSI = 14, PERIODO_ATR = 14;
const JANELA_PIVO = 5;        // candles de cada lado p/ definir topo/fundo
const TOL_NIVEL_PCT = 1.5;    // "testando" um nível se estiver a até 1.5%
const JANELA_NORMAL = 20;     // dias p/ calcular o "normal" de cada ativo
const STOCH_PERIODO = 14;     // estocástico
const MULT_STOP_CURTO = 1.0;  // stop curto = 1x ATR (mínimo seguro)
const MULT_ALVO_31 = 3.0;     // alvo do 3:1 = 3x ATR
const MULT_ALVO_CURTO = 1.4;  // alvo curto = 1.4x ATR (atingível em 1-3 dias)
const STOCH_SUAV = 3;
// -----------------------------

function ema(v, n) {
  if (v.length < n) return [];
  const k = 2 / (n + 1), out = [];
  let s = 0; for (let i = 0; i < n; i++) s += v[i];
  out[n - 1] = s / n;
  for (let i = n; i < v.length; i++) out[i] = v[i] * k + out[i - 1] * (1 - k);
  return out;
}
function computeRSI(c, n) {
  if (c.length < n + 1) return null;
  let g = 0, l = 0;
  for (let i = 1; i <= n; i++) { const d = c[i] - c[i-1]; if (d >= 0) g += d; else l -= d; }
  let ag = g/n, al = l/n;
  for (let i = n+1; i < c.length; i++) { const d = c[i]-c[i-1]; ag=(ag*(n-1)+(d>0?d:0))/n; al=(al*(n-1)+(d<0?-d:0))/n; }
  if (al === 0) return 100;
  return 100 - 100/(1 + ag/al);
}
function computeATR(h, l, c, n) {
  if (c.length < n+1) return null;
  const tr = [];
  for (let i = 1; i < c.length; i++) tr.push(Math.max(h[i]-l[i], Math.abs(h[i]-c[i-1]), Math.abs(l[i]-c[i-1])));
  let a = 0; for (let i = 0; i < n; i++) a += tr[i]; a /= n;
  for (let i = n; i < tr.length; i++) a = (a*(n-1)+tr[i])/n;
  return a;
}
function computeADX(h, l, c, n) {
  if (c.length < n*2+2) return null;
  const tr=[], p=[], m=[];
  for (let i=1;i<c.length;i++){
    const up=h[i]-h[i-1], dn=l[i-1]-l[i];
    p.push((up>dn&&up>0)?up:0); m.push((dn>up&&dn>0)?dn:0);
    tr.push(Math.max(h[i]-l[i],Math.abs(h[i]-c[i-1]),Math.abs(l[i]-c[i-1])));
  }
  function sm(a){const o=[];let s=0;for(let i=0;i<n;i++)s+=a[i];o[n-1]=s;for(let i=n;i<a.length;i++)o[i]=o[i-1]-o[i-1]/n+a[i];return o;}
  const st=sm(tr), sp=sm(p), smi=sm(m), dx=[];
  for(let i=n-1;i<tr.length;i++){if(!st[i]){dx.push(0);continue;}const pd=100*sp[i]/st[i],md=100*smi[i]/st[i],de=pd+md;dx.push(de===0?0:100*Math.abs(pd-md)/de);}
  if(dx.length<n)return null;
  let adx=0;for(let i=0;i<n;i++)adx+=dx[i];adx/=n;
  for(let i=n;i<dx.length;i++)adx=(adx*(n-1)+dx[i])/n;
  const last=tr.length-1;
  return {adx:adx, plusDI:st[last]?100*sp[last]/st[last]:0, minusDI:st[last]?100*smi[last]/st[last]:0};
}

// Estocástico (%K e %D)
function computeStoch(highs, lows, closes, period, suav) {
  const n = closes.length;
  if (n < period + suav) return null;
  const kArr = [];
  for (let i = period - 1; i < n; i++) {
    let hh = -Infinity, ll = Infinity;
    for (let j = i - period + 1; j <= i; j++) { if (highs[j] > hh) hh = highs[j]; if (lows[j] < ll) ll = lows[j]; }
    kArr.push(hh === ll ? 50 : 100 * (closes[i] - ll) / (hh - ll));
  }
  const k = kArr[kArr.length - 1];
  let d = 0; for (let x = kArr.length - suav; x < kArr.length; x++) d += kArr[x];
  d = d / suav;
  return { k: k, d: d };
}

// Suportes/resistências por pivôs (topos e fundos), agrupados em níveis
function niveisSR(h, l, janela, tolPct) {
  const n = h.length, pivos = [];
  for (let i = janela; i < n - janela; i++) {
    let topo = true, fundo = true;
    for (let j = i-janela; j <= i+janela; j++) { if (h[j] > h[i]) topo = false; if (l[j] < l[i]) fundo = false; }
    if (topo) pivos.push(h[i]);
    if (fundo) pivos.push(l[i]);
  }
  pivos.sort((a,b)=>a-b);
  const niveis = [];
  for (const pv of pivos) {
    let achou = false;
    for (const nv of niveis) {
      if (Math.abs(pv-nv.preco)/nv.preco <= tolPct/100) { nv.preco=(nv.preco*nv.toques+pv)/(nv.toques+1); nv.toques++; achou=true; break; }
    }
    if (!achou) niveis.push({preco: pv, toques: 1});
  }
  return niveis;
}

// ===== processamento =====
const _items = $input.all();
let results = [];
for (const _it of _items) if (_it.json && Array.isArray(_it.json.results)) results = results.concat(_it.json.results);

// ===== CLIMA DE MERCADO (Ibovespa) =====
let climaMercado = 'INDISPONIVEL', ibovAdx = null, ibovStoch = null;
const idxIbov = results.findIndex(r => r && typeof r.symbol === 'string' && r.symbol.indexOf('BVSP') !== -1);
if (idxIbov !== -1) {
  const ib = results.splice(idxIbov, 1)[0];   // tira o índice da lista de ações
  const ic = (ib.historicalDataPrice || [])
    .filter(x => x && typeof x.close === 'number' && x.date)
    .sort((a,b)=>a.date-b.date);
  if (ic.length >= 35) {
    const cc = ic.map(x=>x.close), hh = ic.map(x=>x.high), ll = ic.map(x=>x.low);
    const ie9 = ema(cc, EMA_CURTO), ie21 = ema(cc, EMA_LONGO);
    const iAdxObj = computeADX(hh, ll, cc, PERIODO_ADX);
    const iStochObj = computeStoch(hh, ll, cc, STOCH_PERIODO, STOCH_SUAV);
    ibovAdx = iAdxObj ? Number(iAdxObj.adx.toFixed(1)) : null;
    ibovStoch = iStochObj ? Number(iStochObj.k.toFixed(0)) : null;
    const a9 = ie9[ie9.length-1], a21 = ie21[ie21.length-1];
    if (a9 !== undefined && a21 !== undefined && iAdxObj) {
      const emaUp = a9 > a21, diUp = iAdxObj.plusDI >= iAdxObj.minusDI;
      if (iAdxObj.adx < 20) climaMercado = 'LATERAL';
      else if (emaUp && diUp) climaMercado = 'ALTA';
      else if (!emaUp && !diUp) climaMercado = 'BAIXA';
      else climaMercado = 'INDEFINIDO';
    }
  }
}

const saida = [];
for (const ativo of results) {
  const candles = (ativo.historicalDataPrice || [])
    .filter(c => c && typeof c.close === 'number' && c.date)
    .sort((a,b)=>a.date-b.date);
  if (candles.length < 35) {
    saida.push({ json: { simbolo: ativo.symbol||'?', status:'DADOS INSUFICIENTES', interesse:0, resumo:(ativo.symbol||'?')+': histórico curto.' } });
    continue;
  }
  const c = candles.map(x=>x.close), h = candles.map(x=>x.high), l = candles.map(x=>x.low);
  const preco = c[c.length-1], precoOntem = c[c.length-2];

  const e9 = ema(c, EMA_CURTO), e21 = ema(c, EMA_LONGO), e50 = ema(c, EMA_MEDIA);
  const rsi = computeRSI(c, PERIODO_RSI);
  const atr = computeATR(h, l, c, PERIODO_ATR);
  const volumes = candles.map(x=>x.volume||0);

  // ===== NOTA DE ANORMALIDADE (relativa a CADA ativo) =====
  const rets = [];
  for (let k = c.length - JANELA_NORMAL; k < c.length; k++) { if (k > 0) rets.push((c[k]-c[k-1])/c[k-1]); }
  const mediaRet = rets.reduce((a,b)=>a+b,0)/(rets.length||1);
  let variancia = 0; for (const x of rets) variancia += (x-mediaRet)*(x-mediaRet);
  const desvio = Math.sqrt(variancia/(rets.length||1));
  const retHoje = c.length>1 ? (c[c.length-1]-c[c.length-2])/c[c.length-2] : 0;
  const movAnormal = desvio>0 ? Math.abs(retHoje)/desvio : 0;
  const amplitudeHoje = h[h.length-1]-l[l.length-1];
  const amplAnormal = (atr && atr>0) ? amplitudeHoje/atr : 0;
  const volHoje = volumes[volumes.length-1];
  const volMedia = volumes.slice(-JANELA_NORMAL).reduce((a,b)=>a+b,0)/Math.min(JANELA_NORMAL, volumes.length);
  const volAnormal = volMedia>0 ? volHoje/volMedia : 0;
  let anormalidade = 0;
  anormalidade += Math.min(45, movAnormal*18);
  anormalidade += Math.min(25, amplAnormal*15);
  anormalidade += Math.min(30, (volAnormal-1)*20);
  anormalidade = Math.max(0, Math.min(100, Math.round(anormalidade)));
  let rotuloAnorm = anormalidade>=70 ? 'MUITO ANORMAL' : (anormalidade>=45 ? 'ACIMA DO NORMAL' : 'normal');

  // ===== ESTOCÁSTICO (valor) =====
  const stochObj = computeStoch(h, l, c, STOCH_PERIODO, STOCH_SUAV);
  const stoch = stochObj ? stochObj.k : null;
  const adxObj = computeADX(h, l, c, PERIODO_ADX);
  const adx = adxObj ? adxObj.adx : null;

  // força e direção (direção CONFIRMADA pela EMA9 x EMA21)
  let forca = 'FRACA', direcao = 'LATERAL';
  const _e9 = e9[e9.length-1], _e21 = e21[e21.length-1];
  const emaAlta = (_e9 !== undefined && _e21 !== undefined) ? _e9 > _e21 : null;
  if (adx !== null) {
    if (adx >= 25) forca = 'FORTE'; else if (adx >= 20) forca = 'MODERADA'; else forca = 'FRACA';
    if (adx < 20 || emaAlta === null || !adxObj) {
      direcao = 'LATERAL';
    } else {
      const diAlta = adxObj.plusDI >= adxObj.minusDI;
      if (emaAlta && diAlta) direcao = 'ALTA';
      else if (!emaAlta && !diAlta) direcao = 'BAIXA';
      else if (!emaAlta && diAlta) direcao = 'POSSIVEL REVERSAO P/ ALTA';  // repique dentro de uma baixa
      else direcao = 'POSSIVEL REVERSAO P/ BAIXA';                          // fraqueza dentro de uma alta
    }
  }

  // ===== TIMING DE ENTRADA pelo estocástico (relativo à direção) =====
  let timingEntrada = '-';
  if (stoch !== null) {
    const ladoCompra = (direcao === 'ALTA' || direcao === 'POSSIVEL REVERSAO P/ ALTA');
    const ladoVenda  = (direcao === 'BAIXA' || direcao === 'POSSIVEL REVERSAO P/ BAIXA');
    if (ladoCompra) {
      if (stoch >= 80) timingEntrada = 'ESTICADO (tarde p/ comprar)';
      else if (stoch <= 35) timingEntrada = 'BOM (espaco p/ subir)';
      else timingEntrada = 'NEUTRO';
    } else if (ladoVenda) {
      if (stoch <= 20) timingEntrada = 'ESTICADO (tarde p/ vender)';
      else if (stoch >= 65) timingEntrada = 'BOM (espaco p/ cair)';
      else timingEntrada = 'NEUTRO';
    }
  }

  // ===== ALINHAMENTO COM O MERCADO =====
  let vsMercado = '-';
  if (climaMercado === 'ALTA' || climaMercado === 'BAIXA') {
    const ladoAlta = (direcao === 'ALTA' || direcao === 'POSSIVEL REVERSAO P/ ALTA');
    const ladoBaixa = (direcao === 'BAIXA' || direcao === 'POSSIVEL REVERSAO P/ BAIXA');
    if (ladoAlta && climaMercado === 'ALTA') vsMercado = 'A FAVOR DA MARE';
    else if (ladoBaixa && climaMercado === 'BAIXA') vsMercado = 'A FAVOR DA MARE';
    else if (ladoAlta && climaMercado === 'BAIXA') vsMercado = 'CONTRA A MARE';
    else if (ladoBaixa && climaMercado === 'ALTA') vsMercado = 'CONTRA A MARE';
  } else if (climaMercado === 'LATERAL') vsMercado = 'MERCADO LATERAL';

  // ===== STOP e ALVO CURTOS (referência, calibrados no ATR do ativo) =====
  let stopCurto = null, alvoCurto = null;
  if (atr && atr > 0) {
    const compra = (direcao === 'ALTA' || direcao === 'POSSIVEL REVERSAO P/ ALTA');
    const venda  = (direcao === 'BAIXA' || direcao === 'POSSIVEL REVERSAO P/ BAIXA');
    if (compra) { stopCurto = preco - MULT_STOP_CURTO*atr; alvoCurto = preco + MULT_ALVO_CURTO*atr; }
    else if (venda) { stopCurto = preco + MULT_STOP_CURTO*atr; alvoCurto = preco - MULT_ALVO_CURTO*atr; }
  }

  // suportes/resistências
  const niveis = niveisSR(h, l, JANELA_PIVO, TOL_NIVEL_PCT);
  let resAcima = null, supAbaixo = null;
  for (const nv of niveis) {
    if (nv.preco > preco && (resAcima === null || nv.preco < resAcima.preco)) resAcima = nv;
    if (nv.preco < preco && (supAbaixo === null || nv.preco > supAbaixo.preco)) supAbaixo = nv;
  }
  const distRes = resAcima ? (resAcima.preco/preco - 1)*100 : null;

  // ===== AVALIAÇÃO 3:1 (cabe um alvo de 3x o stop antes do próximo nível?) =====
  let alvo31 = null, da31 = 'nao', motivo31 = '';
  if (atr && atr > 0 && (direcao === 'ALTA' || direcao === 'POSSIVEL REVERSAO P/ ALTA' || direcao === 'BAIXA' || direcao === 'POSSIVEL REVERSAO P/ BAIXA')) {
    const compra = (direcao === 'ALTA' || direcao === 'POSSIVEL REVERSAO P/ ALTA');
    const distAlvo = MULT_ALVO_31 * atr;   // 3x o stop (que é 1x ATR)
    if (compra) {
      alvo31 = preco + distAlvo;
      if (resAcima && resAcima.preco < alvo31) { da31 = 'nao'; motivo31 = 'resistência em ' + resAcima.preco.toFixed(2) + ' bloqueia'; }
      else { da31 = 'SIM'; motivo31 = 'caminho livre até ' + alvo31.toFixed(2); }
    } else {
      alvo31 = preco - distAlvo;
      if (supAbaixo && supAbaixo.preco > alvo31) { da31 = 'nao'; motivo31 = 'suporte em ' + supAbaixo.preco.toFixed(2) + ' bloqueia'; }
      else { da31 = 'SIM'; motivo31 = 'caminho livre até ' + alvo31.toFixed(2); }
    }
  } else {
    motivo31 = 'sem direção clara';
  }
  const distSup = supAbaixo ? (1 - supAbaixo.preco/preco)*100 : null;

  // rompimento hoje (close de ontem de um lado, hoje do outro)
  let statusNivel = 'ENTRE NIVEIS', nivelRompido = null;
  for (const nv of niveis) {
    if (precoOntem < nv.preco && preco >= nv.preco) { statusNivel = 'ROMPEU RESISTENCIA'; nivelRompido = nv.preco; }
    if (precoOntem > nv.preco && preco <= nv.preco) { statusNivel = 'ROMPEU SUPORTE'; nivelRompido = nv.preco; }
  }
  if (statusNivel === 'ENTRE NIVEIS') {
    if (distRes !== null && distRes <= TOL_NIVEL_PCT) statusNivel = 'TESTANDO RESISTENCIA';
    else if (distSup !== null && distSup <= TOL_NIVEL_PCT) statusNivel = 'TESTANDO SUPORTE';
  }

  // status do cruzamento (info extra)
  const i9 = e9.length-1, i21 = e21.length-1;
  let cruz = '-';
  if (e9[i9] !== undefined && e21[i21] !== undefined) cruz = e9[i9] >= e21[i21] ? 'EMA9>EMA21' : 'EMA9<EMA21';

  // SCORE DE INTERESSE (0-100): momentos que merecem seu olho
  let interesse = 0;
  if (adx !== null) interesse += Math.min(50, adx * 2);          // força da tendência
  if (statusNivel.indexOf('ROMPEU') !== -1) interesse += 30;     // acabou de romper
  else if (statusNivel.indexOf('TESTANDO') !== -1) interesse += 20; // encostando num nível
  // bônus: rompimento na direção da tendência
  if (statusNivel === 'ROMPEU RESISTENCIA' && direcao === 'ALTA') interesse += 20;
  if (statusNivel === 'ROMPEU SUPORTE' && direcao === 'BAIXA') interesse += 20;
  if (timingEntrada.indexOf('BOM') !== -1) interesse += 10;
  if (timingEntrada.indexOf('ESTICADO') !== -1) interesse -= 15;
  if (vsMercado === 'A FAVOR DA MARE') interesse += 12;
  if (vsMercado === 'CONTRA A MARE') interesse -= 20;
  if (da31 === 'SIM') interesse += 10;
  interesse = Math.max(0, Math.min(100, Math.round(interesse)));

  // ===== CHECKLIST: quantos dos 4 criterios bateram =====
  const okMercado = (vsMercado === 'A FAVOR DA MARE');
  const okDirecao = (direcao === 'ALTA' || direcao === 'BAIXA');
  const okTiming  = (timingEntrada.indexOf('BOM') !== -1);
  const okForca   = (adx !== null && adx >= 25);
  const listaOK = [], listaFalta = [];
  (okMercado ? listaOK : listaFalta).push('MERCADO');
  (okDirecao ? listaOK : listaFalta).push('DIRECAO');
  (okTiming  ? listaOK : listaFalta).push('TIMING');
  (okForca   ? listaOK : listaFalta).push('FORCA');
  const pontos = listaOK.length;
  const criteriosOK = listaOK.length ? listaOK.join(', ') : '-';
  const criteriosFalta = listaFalta.length ? listaFalta.join(', ') : 'nenhum (4/4)';

  const f2 = (x)=> x===null ? '-' : x.toFixed(2);
  const p1 = (x)=> x===null ? '-' : (x>=0?'+':'')+x.toFixed(1)+'%';
  let tendTxt;
  if (direcao === 'ALTA' || direcao === 'BAIXA') tendTxt = 'tend. ' + forca + ' de ' + direcao + (adx!==null?' (ADX '+adx.toFixed(0)+')':'');
  else if (direcao === 'LATERAL') tendTxt = 'LATERAL (sem direcao clara)';
  else tendTxt = '** ' + direcao + ' **' + (adx!==null?' (ADX '+adx.toFixed(0)+')':'');
  const resumo =
    '[' + pontos + '/4] ' + ativo.symbol + ' | ' + tendTxt +
    ' | ' + statusNivel +
    ' | sup: ' + f2(supAbaixo?supAbaixo.preco:null) + ' (' + p1(distSup) + ')' +
    ' | res: ' + f2(resAcima?resAcima.preco:null) + ' (' + p1(distRes) + ')' +
    ' | RSI ' + (rsi!==null?rsi.toFixed(0):'-') +
    ' | STOCH ' + (stoch!==null?stoch.toFixed(0):'-') + ' [' + timingEntrada + ']' +
    (stopCurto!==null ? ' | stop~ ' + stopCurto.toFixed(2) + ' | alvo~ ' + alvoCurto.toFixed(2) : '') +
    ' | MERCADO ' + climaMercado + ' -> ' + vsMercado +
    ' | ANORM ' + anormalidade + ' (' + rotuloAnorm + ')' +
    ' | 3:1? ' + da31 +
    ' | INTERESSE ' + interesse +
    ' | OK: ' + criteriosOK + (criteriosFalta==='nenhum (4/4)' ? '' : ' | FALTA: ' + criteriosFalta);

  saida.push({ json: {
    pontos: pontos,
    criteriosOK: criteriosOK,
    criteriosFalta: criteriosFalta,
    da31: da31,
    alvo31: alvo31!==null?Number(alvo31.toFixed(2)):null,
    motivo31: motivo31,
    simbolo: ativo.symbol,
    preco: Number(preco.toFixed(2)),
    forcaTendencia: forca,
    direcao: direcao,
    adx: adx!==null?Number(adx.toFixed(1)):null,
    statusNivel: statusNivel,
    suporteProximo: supAbaixo?Number(supAbaixo.preco.toFixed(2)):null,
    distSupPct: distSup!==null?Number(distSup.toFixed(2)):null,
    resistenciaProxima: resAcima?Number(resAcima.preco.toFixed(2)):null,
    distResPct: distRes!==null?Number(distRes.toFixed(2)):null,
    nivelRompido: nivelRompido?Number(nivelRompido.toFixed(2)):null,
    cruzamentoEMA: cruz,
    rsi: rsi!==null?Number(rsi.toFixed(1)):null,
    atr: atr!==null?Number(atr.toFixed(2)):null,
    stoch: stoch!==null?Number(stoch.toFixed(0)):null,
    timingEntrada: timingEntrada,
    climaMercado: climaMercado,
    vsMercado: vsMercado,
    stopCurtoSugerido: stopCurto!==null?Number(stopCurto.toFixed(2)):null,
    alvoCurtoSugerido: alvoCurto!==null?Number(alvoCurto.toFixed(2)):null,
    movDesvios: Number(movAnormal.toFixed(1)),
    volVezes: Number(volAnormal.toFixed(1)),
    anormalidade: anormalidade,
    rotuloAnormalidade: rotuloAnorm,
    interesse: interesse,
    resumo: resumo
  } });
}

saida.sort((a,b)=>{
  const pa=(a.json.pontos||0), pb=(b.json.pontos||0);
  if (pb!==pa) return pb-pa;
  return (b.json.interesse||0)-(a.json.interesse||0);
});
return saida;

// ============================================================
//  ATUALIZAR MEMÓRIA — junta o histórico já salvo (CSV) com os
//  candles novos da rodada de hoje, sem duplicar datas.
//  Entrada (input): linhas do CSV antigo (vindas do "Extrair CSV").
//  Também lê os candles do node "Buscar Candles (brapi)".
//  Modo do node: "Run Once for All Items"
// ============================================================

const mapa = new Map(); // chave: TICKER|DATA  ->  {ticker, date, close}

// 1) carregar o histórico que já existe no CSV
for (const it of $input.all()) {
  const j = it.json || {};
  if (j.ticker && j.date) {
    mapa.set(j.ticker + '|' + j.date, {
      ticker: String(j.ticker),
      date: String(j.date),
      close: Number(j.close)
    });
  }
}

// 2) acrescentar os candles novos vindos da brapi
const lotes = $('Buscar Candles (brapi)').all();
for (const it of lotes) {
  const results = (it.json && it.json.results) || [];
  for (const ativo of results) {
    const sym = ativo.symbol;
    if (!sym) continue;
    const candles = ativo.historicalDataPrice || [];
    for (const c of candles) {
      if (!c || typeof c.close !== 'number' || !c.date) continue;
      const d = new Date(c.date * 1000).toISOString().slice(0, 10); // AAAA-MM-DD
      mapa.set(sym + '|' + d, { ticker: sym, date: d, close: c.close });
    }
  }
}

// 3) devolver tudo ordenado (ticker, depois data)
const linhas = Array.from(mapa.values())
  .sort((a, b) => a.ticker.localeCompare(b.ticker) || a.date.localeCompare(b.date));

return linhas.map(l => ({ json: l }));
